# System.Runtime.Intrinsics.Arm.AdvSimd — absolute compares and differences, pairwise
# and IEEE-754 maxNum/minNum arithmetic, bit counts, ORN, and the remaining Scalar
# overloads (FADD Sd zeroes the register's other lane; the x1 integer forms are whole).
# FACGT/FACGE compare magnitudes; the LessThan forms are the same instruction with
# the operands swapped, which the vcalt/vcale intrinsics spell.
AbsoluteCompareGreaterThan(v{W}f32,v{W}f32) = vcagt{q}_f32($0, $1) for W in 64,128
AbsoluteCompareGreaterThanOrEqual(v{W}f32,v{W}f32) = vcage{q}_f32($0, $1) for W in 64,128
AbsoluteCompareLessThan(v{W}f32,v{W}f32) = vcalt{q}_f32($0, $1) for W in 64,128
AbsoluteCompareLessThanOrEqual(v{W}f32,v{W}f32) = vcale{q}_f32($0, $1) for W in 64,128
AbsoluteDifference(v{W}{T},v{W}{T}) = vabd{q}_{neon}($0, $1) for W in 64,128 for T in i8,u8,i16,u16,i32,u32,f32
AbsoluteDifferenceAdd(v{W}{T},v{W}{T},v{W}{T}) = vaba{q}_{neon}($0, $1, $2) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
AbsScalar(v64{T}) = dn2cpp_isa_lane0<8>(vget_lane_{neon}(vabs_{neon}($0), 0)) for T in f32,f64
AddPairwise(v64{T},v64{T}) = vpadd_{neon}($0, $1) for T in i8,u8,i16,u16,i32,u32,f32
AddScalar(v64{T},v64{T}) = dn2cpp_isa_lane0<8>(vget_lane_{neon}(vadd_{neon}($0, $1), 0)) for T in f32,f64,i64,u64
LeadingSignCount(v{W}{T}) = vcls{q}_{neon}($0) for W in 64,128 for T in i8,i16,i32
LeadingZeroCount(v{W}{T}) = vclz{q}_{neon}($0) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
MaxNumber(v{W}f32,v{W}f32) = vmaxnm{q}_f32($0, $1) for W in 64,128
MaxNumberScalar(v64{T},v64{T}) = dn2cpp_isa_lane0<8>(vget_lane_{neon}(vmaxnm_{neon}($0, $1), 0)) for T in f32,f64
MaxPairwise(v64{T},v64{T}) = vpmax_{neon}($0, $1) for T in i8,u8,i16,u16,i32,u32,f32
MinNumber(v{W}f32,v{W}f32) = vminnm{q}_f32($0, $1) for W in 64,128
MinNumberScalar(v64{T},v64{T}) = dn2cpp_isa_lane0<8>(vget_lane_{neon}(vminnm_{neon}($0, $1), 0)) for T in f32,f64
MinPairwise(v64{T},v64{T}) = vpmin_{neon}($0, $1) for T in i8,u8,i16,u16,i32,u32,f32
NegateScalar(v64{T}) = dn2cpp_isa_lane0<8>(vget_lane_{neon}(vneg_{neon}($0), 0)) for T in f32,f64
OrNot(v{W}{T},v{W}{T}) = vorn{q}_{uT}($0:{uT}, $1:{uT}) for W in 64,128 for T in i8,u8,i16,u16,i32,u32,i64,u64,f32,f64
PopCount(v{W}{T}) = vcnt{q}_{neon}($0) for W in 64,128 for T in i8,u8
SubtractScalar(v64{T},v64{T}) = dn2cpp_isa_lane0<8>(vget_lane_{neon}(vsub_{neon}($0, $1), 0)) for T in f32,f64,i64,u64
